const loja = $('Para Cada Loja').first().json;
const pedidos = $('Buscar Pedidos de Ontem').all().map(i => i.json);
const entregadores = $('Buscar Entregadores da Loja').all().map(i => i.json);

const hoje = new Date();
const ontem = new Date(hoje);
ontem.setDate(ontem.getDate() - 1);
const dataFormatada = ontem.toLocaleDateString('pt-BR');

if (!pedidos || pedidos.length === 0) {
  return [{
    json: {
      telefone_admin: loja.telefone_admin,
      instancia: loja.instancia_whatsapp,
      nome_loja: loja.nome,
      mensagem: `?? *Relatorio ${loja.nome} - ${dataFormatada}*\n\nNenhum pedido registrado ontem.`
    }
  }];
}

const porProduto = {};
pedidos.forEach(p => {
  const prod = p.produto_nome ?? 'Nao informado';
  porProduto[prod] = (porProduto[prod] ?? 0) + 1;
});

const porEntregador = {};
pedidos.forEach(p => {
  if (p.entregador_id) {
    const ent = entregadores.find(e => e.id === p.entregador_id);
    const nome = ent?.nome ?? 'Entregador ' + p.entregador_id;
    porEntregador[nome] = (porEntregador[nome] ?? 0) + 1;
  }
});

const despachados = pedidos.filter(p => p.status === 'despachado').length;
const entregues = pedidos.filter(p => p.status === 'entregue').length;
const cancelados = pedidos.filter(p => p.status === 'cancelado').length;

const faturamento = pedidos.reduce((acc, p) => acc + (parseFloat(p.valor_total) || 0), 0);

const produtosTexto = Object.entries(porProduto)
  .map(([nome, qtd]) => `   . ${nome}: ${qtd} pedido${qtd > 1 ? 's' : ''}`)
  .join('\n');

const entregadoresTexto = Object.entries(porEntregador)
  .map(([nome, qtd]) => `   . ${nome}: ${qtd} entrega${qtd > 1 ? 's' : ''}`)
  .join('\n');

const mensagem = `?? *Relatorio ${loja.nome}*
?? ${dataFormatada}

*Total de pedidos: ${pedidos.length}*

?? *Por produto:*
${produtosTexto}

?? *Por entregador:*
${entregadoresTexto || '   . Nao informado'}

?? *Status:*
   . Despachados: ${despachados}
   . Entregues: ${entregues}
   . Cancelados: ${cancelados}

?? *Faturamento estimado: R$${faturamento.toFixed(2)}*

_Relatorio gerado automaticamente pela UpGasIA_ ??`;

return [{
  json: {
    telefone_admin: loja.telefone_admin,
    instancia: loja.instancia_whatsapp,
    nome_loja: loja.nome,
    mensagem
  }
}];

